function i(n){return!n||n<=0?null:9.81*n*n/8}function s(n){return!n||n<=0?null:9.81*n/2}function b(n,u){const t=Number(n),o=Number(u);if(!t||t<=0||!o||o<=0)return null;const r=i(t),a=s(t),l=e=>Math.round(e*1e3)/1e3,c=e=>Math.round(e*100)/100;return{height:l(r),heightCm:Math.round(r*1e3)/10,rsi:c(r/o),takeoffVelocity:c(a)}}const m=[{min:1.3,max:1/0,label:"스피드·파워",color:"blue"},{min:1,max:1.3,label:"근파워",color:"green"},{min:.75,max:1,label:"근력·파워",color:"yellow"},{min:.5,max:.75,label:"근비대·근력",color:"orange"},{min:0,max:.5,label:"최대근력",color:"red"}];function h(n){return m.find(u=>n>=u.min&&n<u.max)||null}function d(n,u){const t=Number(n),o=Number(u);if(!t||t<=0||!o||o<=0)return null;const r=t/o;return{meanVelocity:(l=>Math.round(l*100)/100)(r),zone:h(r)}}function x(n,u){const t=Number(n);if(!t||t<=0)return null;const o=i(t),r=Math.round(o*1e3)/10,a=s(t),l=f=>Math.round(f*100)/100;let c=null;const e=Number(u);return e&&e>0&&(c=Math.round(60.7*r+45.3*e-2055)),{heightCm:r,takeoffVelocity:l(a),peakPower:c}}export{m as V,d as a,x as b,b as c};
